from datetime import datetime

class Person:

    def __init__(self, name, phone, bi, attendance_type, ticket):
        self.__bi = bi
        self.__name = name
        self.__phone = phone
        self.__ticket = ticket
        self.__type = attendance_type

        self.__arrival_time = datetime.now() #altura de chegada
        self.__service_time = datetime.now() #quanto tempo demorou até ser atendido
        
    @property
    def bi(self):
        return self.__bi
    
    @bi.setter
    def bi(self, value):
        self.__bi = value
        
    @property
    def name(self):
        return self.__name
    
    @name.setter
    def name(self, value):
        self.__name = value
        
    @property
    def phone(self):
        return self.__phone
    
    @phone.setter
    def phone(self, value):
        self.__phone = value
        
    @property
    def ticket(self):
        return self.__ticket
    
    @ticket.setter
    def ticket(self, value):
        self.__ticket = value

    @property
    def type(self):
        return self.__type
    
    @type.setter
    def type(self, value):
        self.__type = value
        
    def __str__(self):
        return f"{self.ticket} | {self.name} | {self.type}"

    @property
    def arrival_time(self):
        return self.__arrival_time

    @arrival_time.setter
    def arrival_time(self, value):
        self.__arrival_time = value

    @property
    def service_time(self):
        return self.__service_time

    @service_time.setter
    def service_time(self, value):
        self.__service_time = value


